import{_ as i,C as r,o as s,c as l,j as t,a as e,E as o,aj as a}from"./chunks/framework.m090XgxO.js";const q=JSON.parse('{"title":"Reasoning","description":"","frontmatter":{},"headers":[],"relativePath":"components/reasoning.md","filePath":"components/reasoning.md","lastUpdated":1789206102000}'),h={name:"components/reasoning.md"},g={id:"reasoning",tabindex:"-1"};function b(u,d,p,x,f,m){const n=r("Badge"),c=r("XhDemo");return s(),l("div",null,[t("h1",g,[d[0]||(d[0]=e("Reasoning ",-1)),o(n,{type:"info",text:"思考过程"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#reasoning","aria-label":'Permalink to "Reasoning <Badge type="info" text="思考过程" />"'},"​",-1))]),d[3]||(d[3]=a('<p>模型「想」的那一段：默认跟着写入自动展开，想完自动收起，用户动手过一次就不再自动。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/reasoning" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/reasoning.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/reasoning" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/reasoning" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/reasoning.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>想的时候自动展开、想完自动收起；状态文案由组件按在不在想与时长给出</p>',4)),o(c,{src:"reasoning/01-basic"}),d[4]||(d[4]=t("h2",{id:"示例",tabindex:"-1"},[e("示例 "),t("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),d[5]||(d[5]=t("h3",{id:"无壳内联形态",tabindex:"-1"},[e("无壳内联形态 "),t("a",{class:"header-anchor",href:"#无壳内联形态","aria-label":'Permalink to "无壳内联形态"'},"​")],-1)),d[6]||(d[6]=t("p",null,"ghost 档不占一块面，开关收成只占文字宽度的小药丸，适合在一段回答里穿插好几处",-1)),o(c,{src:"reasoning/02-inline"}),d[7]||(d[7]=t("h3",{id:"语气与尺寸",tabindex:"-1"},[e("语气与尺寸 "),t("a",{class:"header-anchor",href:"#语气与尺寸","aria-label":'Permalink to "语气与尺寸"'},"​")],-1)),d[8]||(d[8]=t("p",null,"tone 换指示符与状态文案的色族，size 换标题行与正文的几何档；五份都挂在思考中，正文自动展开",-1)),o(c,{src:"reasoning/03-tone-size"}),d[9]||(d[9]=t("h3",{id:"受控开合与禁用",tabindex:"-1"},[e("受控开合与禁用 "),t("a",{class:"header-anchor",href:"#受控开合与禁用","aria-label":'Permalink to "受控开合与禁用"'},"​")],-1)),d[10]||(d[10]=t("p",null,"open 交给宿主：外面一颗钮统一开合几段思考，自动开合让位；disabled 的那一段开关按不动，停在给定的那一档",-1)),o(c,{src:"reasoning/04-controlled"}),d[11]||(d[11]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>展示推理模型吐出的思考过程，且它是边想边显示的。</li><li>想让读者能回头看「它当时是怎么想的」，但默认不占版面。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>展示的是一次工具调用：用<a href="./tool-call">工具调用</a>，两者共用同一台机器但正文形态不同。</li><li>内容不是散文而是结构化数据：那属于工具调用的参数与结果。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>自动开合与<a href="./tool-call">工具调用</a>是同一台机器：<strong>锁存靠转移的放置位置，不靠一个布尔位</strong>， 用户点过一次之后阶段变化就永久够不着自动开合。</li><li>「想了多久」由两个时刻算出来，<strong>任一缺席即算不出来</strong>——流被中止时兜底收尾不写结束时刻， 推理块会只有起点没有终点，这一档必须接得住。</li><li>名字与时长都排在开关里，「思考过程，用时 12 秒」整句自然构成开关的可访问名。</li><li>状态文案由组件给：在想时是「在想」那一句，想完把秒数代进 <code>thoughtFor</code> 的 <code>{seconds}</code>， 算不出时长就回落折叠区的名字。名字位不写内容时显示的就是它。</li><li>形态三档：<code>outline</code> 描边、<code>subtle</code> 底色分区（缺省档）、<code>ghost</code> 无壳内联—— 一段回答里穿插好几处思考时用 <code>ghost</code>，它不占一块面，开关收成只占文字宽度的一枚小药丸。</li><li>开合有动画：展开与收起是行高与内缩同帧动，收起在动画播完之后才真的落成隐藏。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-reasoning&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhReasoningContent</code> <code>XhReasoningDuration</code> <code>XhReasoningIcon</code> <code>XhReasoningIndicator</code> <code>XhReasoningLabel</code> <code>XhReasoningRoot</code> <code>XhReasoningTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useReasoning</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/reasoning.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;reasoning&quot;</code>：<strong><code>root</code></strong> · <strong><code>trigger</code></strong> · <code>icon</code> · <code>indicator</code> · <code>label</code> · <code>duration</code> · <strong><code>content</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>endTime</code></td><td><code>number</code></td><td></td><td>思考结束的时刻。<strong>可能缺席</strong>：流被中止时兜底收尾不写这一个。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td></td></tr><tr><td><code>startTime</code></td><td><code>number</code></td><td></td><td>开始思考的时刻，毫秒时间戳。</td></tr><tr><td><code>streaming</code></td><td><code>boolean</code></td><td></td><td>还在思考。适配器把它折成机器的 running。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ReasoningTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td>形态：outline 描边、subtle 底色分区（缺省档）、ghost 无壳内联。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>ToolCallOpenChangeDetails</code></td><td>开合变化；detail 为 <code>{ open: boolean, source: &#39;user&#39; | &#39;auto&#39; | &#39;api&#39; }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhReasoningRoot</code></td><td><code>default</code></td><td><code>ReasoningRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useReasoning</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>streaming</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>durationMs</code></td><td><code>number | undefined</code></td><td>想了多久，毫秒；两个时刻任一缺席即 undefined。</td></tr><tr><td><code>statusText</code></td><td><code>string</code></td><td>当前该显示哪句状态文案，已按 streaming 与时长选好。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getIconProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDurationProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在折叠开关上且未禁用</td><td>展开或收起思考正文，并把自动开合永久停用</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>icon</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>trigger</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;region&#39;</td></tr></tbody></table><ul><li>开关带 <code>aria-expanded</code> 与 <code>aria-controls</code>，正文区是 <code>role=region</code> 且由开关命名。</li><li>不再另发 <code>aria-label</code>：另发会盖过节点里的文字，两者不一致时读屏念的与屏幕上看到的对不上。</li><li>自己不开活区：整段思考每来一个字都播报会把读屏刷爆。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/reasoning.css</code> 按部件选择：<code>[data-scope=&quot;reasoning&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-streaming</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td><code>data-streaming</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>icon</code></td><td><code>data-streaming</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>label</code></td><td><code>data-streaming</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>duration</code></td><td><code>data-streaming</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-reasoning-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code><br><code>variant=outline</code></td><td><code>--xh-bg-subtle</code><br><code>--xh-bg-surface</code></td><td>reasoning 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-border</code></td><td><code>root</code></td><td><code>border-color</code></td><td><code>variant=outline</code></td><td><code>--xh-border-subtle</code></td><td>reasoning 的 root 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-content-fg</code></td><td><code>content</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>reasoning 的 content 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-content-font-size</code></td><td><code>content</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-secondary-size</code></td><td>reasoning 的 content 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-content-leading</code></td><td><code>content</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-text-prose-leading</code></td><td>reasoning 的 content 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-content-pe</code></td><td><code>content</code></td><td><code>padding-inline-end</code></td><td><code>default</code></td><td><code>--xh-reasoning-px</code></td><td>reasoning 的 content 部件 padding-inline-end 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-content-ps</code></td><td><code>content</code></td><td><code>padding-inline-start</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>reasoning 的 content 部件 padding-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-duration-fg</code></td><td><code>duration</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>reasoning 的 duration 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-duration-font-size</code></td><td><code>duration</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-caption-size</code></td><td>reasoning 的 duration 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-font-size</code></td><td><code>trigger</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_reasoning-font-size</code></td><td>reasoning 的 trigger 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-icon-fg</code></td><td><code>icon</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>reasoning 的 icon 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-icon-size</code></td><td><code>root</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-glyph-size-text</code></td><td>reasoning 的 root 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-icon-streaming-fg</code></td><td><code>icon</code></td><td><code>color</code></td><td><code>streaming</code></td><td><code>--xh-fg-muted</code></td><td>reasoning 的 icon 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-indicator-fg</code></td><td><code>indicator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>reasoning 的 indicator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>reasoning 的 label 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-label-streaming-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>@media (prefers-reduced-motion: reduce)</code><br><code>@media print</code><br><code>motion=reduce</code><br><code>streaming</code><br><code>where([data-motion=&#39;reduce&#39;])</code></td><td><code>--xh-fg-default</code></td><td>reasoning 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-px</code></td><td><code>content</code><br><code>trigger</code></td><td><code>margin-inline-start</code><br><code>padding-inline</code><br><code>padding-inline-end</code></td><td><code>default</code></td><td><code>--xh-_reasoning-px</code></td><td>reasoning 的 content、trigger 部件 margin-inline-start、padding-inline、padding-inline-end 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-py</code></td><td><code>*</code><br><code>content</code><br><code>trigger</code></td><td><code>padding-block</code><br><code>padding-block-end</code></td><td><code>@keyframes xh-reasoning-collapse</code><br><code>@keyframes xh-reasoning-expand</code><br><code>default</code></td><td><code>--xh-_reasoning-py</code></td><td>reasoning 的 *、content、trigger 部件 padding-block、padding-block-end 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-surface</code></td><td>reasoning 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-rail</code></td><td><code>content</code></td><td><code>border-inline-start</code></td><td><code>default</code></td><td><code>--xh-border-subtle</code></td><td>reasoning 的 content 部件 border-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-rail-inset</code></td><td><code>content</code></td><td><code>margin-inline-start</code></td><td><code>default</code></td><td><code>--xh-reasoning-px</code></td><td>reasoning 的 content 部件 margin-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-rail-width</code></td><td><code>content</code></td><td><code>border-inline-start</code></td><td><code>default</code></td><td><code>--xh-stroke-thin</code></td><td>reasoning 的 content 部件 border-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-shadow</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>default</code><br><code>tone</code></td><td><code>--xh-elevation-raised</code></td><td>reasoning 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-shimmer-duration</code></td><td><code>label</code></td><td><code>animation</code></td><td><code>streaming</code></td><td><code>--xh-shimmer-duration</code></td><td>reasoning 的 label 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-shimmer-from</code></td><td><code>label</code></td><td><code>background-image</code></td><td><code>streaming</code></td><td><code>--xh-fg-subtle</code></td><td>reasoning 的 label 部件 background-image 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-shimmer-to</code></td><td><code>label</code></td><td><code>background-image</code></td><td><code>streaming</code></td><td><code>--xh-fg-default</code></td><td>reasoning 的 label 部件 background-image 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-tone-bar</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>tone</code></td><td><code>--xh-stroke-thick</code></td><td>reasoning 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-tone-fg</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>tone</code></td><td><code>--xh-_tone-soft</code></td><td>reasoning 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-trigger-bg-hover</code></td><td><code>trigger</code></td><td><code>background</code></td><td><code>hover</code><br><code>not(:disabled)</code></td><td><code>--xh-bg-subtle-hover</code></td><td>reasoning 的 trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-trigger-fg</code></td><td><code>trigger</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>reasoning 的 trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-trigger-gap</code></td><td><code>trigger</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>reasoning 的 trigger 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-reasoning-trigger-radius</code></td><td><code>root</code><br><code>trigger</code></td><td><code>border-radius</code></td><td><code>variant=ghost</code></td><td><code>--xh-shape-control</code></td><td>reasoning 的 root、trigger 部件 border-radius 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-reasoning-collapse</code> · <code>xh-reasoning-expand</code> · <code>xh-reasoning-fade-in</code> · <code>xh-reasoning-shimmer</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>color</code> · <code>rotate</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：退场由适配器的退场闸门把关，动画播完才真收起。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>正文用<a href="./markdown-stream">流式正文</a>：思考过程是散文，与工具调用的等宽结构块不同。 正文<strong>放在一个容器里</strong>：展开动画量的是第一行的行高，散落的多个兄弟节点收不干净。</li><li>多段推理并排、要一次只展开一段时套<a href="./accordion">手风琴</a>。</li><li>要让「在想 → 想完」被读屏播报：把会话级的那一个活区放在推理块外面， 由它念一句结果——组件自己不开活区（见下），整段思考每来一个字都播报会把读屏刷爆。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>想完之后把时长显示出来：读者据此判断这段推理值不值得展开。</li><li>默认收起。思考过程是给想看的人看的，不是回答本身。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把思考过程当回答显示：两者混在一起时读者分不清哪句是结论。</li><li>用它承载工具调用的参数与结果：正文排版是散文那一套，等宽结构块在这里会挤成一团。</li></ul>',54))])}const P=i(h,[["render",b]]);export{q as __pageData,P as default};
